class Renderer(Protocol):
    """What the accessors reach the locale engine through."""

    def render(self, key: str, params: Mapping[str, object] = {}) -> str:
        """The message with a key, rendered with its parameters."""
        ...

    def entity(self, key: str) -> "EntityForms":
        """A catalogued entity's forms in the current locale."""
        ...


@dataclass(frozen=True)
class EntityForms:
    """A catalogued entity's forms in the current locale."""

    iast: str

    name: str

    prose: str

    short: Optional[str] = None

    glyph: Optional[str] = None

    gender: Optional[Gender] = None

    @classmethod
    def of(cls, raw: object) -> EntityForms:
        """The forms as the boundary hands them out, whether as the JSON
        text or as the object it parses to.
        """
        forms = json.loads(raw) if isinstance(raw, str) else raw
        assert isinstance(forms, dict)

        def text(form: str) -> Optional[str]:
            found = forms.get(form)
            return found if isinstance(found, str) else None

        return cls(
            iast=text("iast") or "",
            name=text("name") or "",
            prose=text("prose") or "",
            short=text("short"),
            glyph=text("glyph"),
            gender=next(
                (g for g in Gender if g.value == text("gender")), None
            ),
        )


